const E=escapeHTML;const key='eagle-demo-workspace-v1';let db;try{db=DemoData.validate(JSON.parse(localStorage.getItem(key)))}catch{db=DemoData.seed()}let current='',filter='All',query='',sort='Newest',selectedTab='';
const routes=[['','Dashboard','Overview'],['attack-paths','Attack Vectors','Overview'],['ask','Ask eagle-i','Overview'],['alerts','Alerts','Operations'],['incidents','Incidents','Operations'],['alerts/suppressions','Suppression Rules','Operations'],['monitoring','Monitoring','Operations'],['history','History','Operations'],['attack-surface','Attack Surface','Attack Surface'],['assets','Asset Inventory','Attack Surface'],['supply-chain','Supply Chain','Attack Surface'],['intelligence','Intelligence Hub','Threat Intelligence'],['dark-web','Threat Feeds','Threat Intelligence'],['rfi','Intel RFI','Threat Intelligence'],['exposure','Exposure Score','Exposure'],['brand','Brand Threats','Exposure'],['executives','Executive Shield','Exposure'],['exposure/credentials','Credential Exposure','Exposure'],['assessment','Posture Assessment','Reporting'],['reports','Reports','Reporting'],['org/settings','Org Settings','Team'],['demo-data','Demo Data','Demo']];
const dashboard=document.querySelector('main');dashboard.id='dashboard-page';const view=document.createElement('main');view.id='route-page';view.hidden=true;dashboard.after(view);let previousGroup='';document.querySelector('#nav').innerHTML='<h2>eagle-i</h2><p>THREAT INTELLIGENCE</p><b id="nav-org"></b>'+routes.map(([r,n,g])=>{const heading=g!==previousGroup?`<label class="nav-group">${g}</label>`:'';previousGroup=g;return heading+`<a href="#/dashboard${r?'/'+r:''}" data-route="${r}">${n}</a>`}).join('');document.querySelectorAll('aside a').forEach(a=>a.onclick=()=>document.querySelector('#nav').hidden=true);document.querySelector('header>span').id='breadcrumb';document.querySelector('header .pink').outerHTML='<button class="pink" aria-label="View alerts" onclick="location.hash=\'/dashboard/alerts\'">99+</button>';document.querySelector('header b').outerHTML='<button id="user-menu">Demo User ▾</button>';document.querySelector('#user-menu').onclick=()=>modal('Demo User','<p>Demo workspace · Changes are saved in this browser.</p><button onclick="dialog.close();location.hash=\'/dashboard/org/settings\'">Organization settings</button> <button onclick="dialog.close();location.hash=\'/dashboard/demo-data\'">Manage demo data</button>');
function save(){try{localStorage.setItem(key,JSON.stringify(db))}catch{toast('Browser storage is full. Export your data to keep a copy.')}syncDashboard()}
function badge(s){return `<span class="status ${s==='Critical'?'pink':s==='High'?'orange':s==='Low'||s==='Resolved'?'green':'gold'}">${E(s)}</span>`}
function stats(items){return `<div class="stat-grid">${items.map(([n,v])=>`<div class="metric"><span>${E(n)}</span><strong>${E(v)}</strong></div>`).join('')}</div>`}
function card(title,content){return `<section class="panel"><h2>${title}</h2><div class="body">${content}</div></section>`}
function intro(title,desc,actions='',eyebrow=''){view.innerHTML=`<div class="page-intro"><div><label>${eyebrow}</label><h1>${title}</h1><p>${desc}</p></div><div class="page-actions">${actions}</div></div>`}
function action(label,fn,cls=''){return `<button class="${cls}" data-do="${fn}">${label}</button>`}
function tabs(items){return `<div class="tabs" role="tablist">${items.map(t=>`<button role="tab" aria-selected="${(selectedTab||items[0])===t}" data-tab="${E(t)}">${t}</button>`).join('')}</div>`}
function table(type,options={}){let data=db[type].filter(r=>(filter==='All'||r.severity===filter||r.status===filter||r.type===filter)&&(!query||JSON.stringify(r).toLowerCase().includes(query.toLowerCase())));if(sort==='Name')data.sort((a,b)=>a.title.localeCompare(b.title));if(sort==='Severity')data.sort((a,b)=>['Critical','High','Medium','Low'].indexOf(a.severity)-['Critical','High','Medium','Low'].indexOf(b.severity));if(sort==='Oldest')data.reverse();return `<div class="table-tools"><input id="record-search" aria-label="Search records" placeholder="Filter by title, asset, or message…" value="${E(query)}"><select id="record-filter" aria-label="Filter records">${['All',...(options.filters||['Critical','High','Medium','Low','Open','Resolved'])].map(v=>`<option ${filter===v?'selected':''}>${v}</option>`).join('')}</select><select id="record-sort" aria-label="Sort records">${['Newest','Oldest','Name','Severity'].map(v=>`<option ${sort===v?'selected':''}>${v}</option>`).join('')}</select>${action('Export CSV','export:'+type)}</div><p class="result-count">${data.length} shown / ${db[type].length} total</p><div class="table-wrap"><table><thead><tr><th>${options.name||'Finding'}</th><th>Asset / Target</th><th>Severity</th><th>Status</th><th>Type</th><th></th></tr></thead><tbody>${data.map(r=>`<tr><td><button class="text-button" data-detail="${type}:${r.id}">${E(r.title)}</button><small>${E(r.date)}</small></td><td>${E(r.asset)}</td><td>${badge(r.severity)}</td><td>${E(r.status)}</td><td>${E(r.type)}</td><td><button data-edit="${type}:${r.id}" aria-label="Edit ${E(r.title)}">Edit</button></td></tr>`).join('')||'<tr><td colspan="6"><div class="empty"><h3>No matching records</h3><p>Add dummy data or change your filters.</p></div></td></tr>'}</tbody></table></div>`}
function listing(type,title,desc,opts={}){intro(title,desc,action(opts.add||'Add dummy record','add:'+type,'primary'),opts.group||'');view.innerHTML+=stats([['TOTAL',db[type].length],['CRITICAL',db[type].filter(r=>r.severity==='Critical').length],['HIGH',db[type].filter(r=>r.severity==='High').length],['OPEN / ACTIVE',db[type].filter(r=>!['Closed','Resolved'].includes(r.status)).length]])+table(type,opts)}
function syncDashboard(){document.querySelector('#nav-org').textContent=db.organization.name;dashboard.querySelector('h1').textContent=db.organization.name;dashboard.querySelector('.org h3').innerHTML=E(db.organization.name)+' <span class="tag">ACTIVE</span><span class="tag gold">'+E(db.organization.industry.toUpperCase())+'</span>';let counts=[db.assets.filter(r=>r.status==='Monitoring').length,db.alerts.filter(r=>r.status==='Open').length,db.credentials.length];dashboard.querySelectorAll('.hero-stats strong').forEach((e,i)=>e.textContent=counts[i]);dashboard.querySelector('.ring strong').textContent=db.score;dashboard.querySelectorAll('.metrics .metric strong').forEach((e,i)=>{e.innerHTML=E([db.score,counts[1],db.assets.length,counts[2],0][i])+` <small>${['of 100',db.alerts.length+' total','assets','records','avg hours'][i]}</small>`});const replace=(id,html)=>document.getElementById(id).querySelector('.body').innerHTML=html;replace('Live-Threat-Feed',db.alerts.slice(0,7).map(r=>row(E(r.title),'',E(r.severity+' · '+r.asset))).join(''));replace('Exposed-Credentials',db.credentials.slice(0,8).map(r=>row(E(r.title),E(r.type),E(r.asset))).join(''));replace('Top-Exposed-Assets',db.assets.slice(0,5).map(r=>row(E(r.title),E(r.severity),E(r.type))).join(''));replace('Exposure-Score',`<div class="empty"><div class="big">${db.score}</div><span class="tag gold">${db.score>=60?'HIGH':db.score>=30?'MODERATE':'LOW'} RISK</span><p>Exposure score for the current demo dataset.</p></div>`);replace('Recent-Searches',db.history.slice(0,5).map(r=>row(E(r.title),E(r.status),E(r.date))).join(''));replace('Remediation-Queue',db.alerts.filter(r=>r.status==='Open').slice(0,6).map(r=>row(E(r.title),E(r.severity),E(r.asset))).join(''));replace('Takedowns',stats([['OPEN',db.brand.filter(r=>r.status!=='Resolved').length],['RESOLVED',db.brand.filter(r=>r.status==='Resolved').length]]));}
function navigate(){const path=location.hash.replace(/^#\/?dashboard\/?/,'').replace(/^\//,'');current=routes.some(r=>r[0]===path)?path:'';filter='All';query='';selectedTab='';render();window.scrollTo(0,0)}
function render(){const route=routes.find(r=>r[0]===current);document.title=route[1]+' · '+db.organization.name+' Demo';document.querySelector('#breadcrumb').textContent=current?'Dashboard / '+route[1]:'Dashboard';document.querySelectorAll('[data-route]').forEach(a=>a.classList.toggle('active',a.dataset.route===current));dashboard.hidden=!!current;view.hidden=!current;if(!current){syncDashboard();return}switch(current){
case 'alerts':listing('alerts','Alerts','Review, triage, snooze, and resolve sample security findings.',{group:'OPERATIONS',filters:['Critical','High','Medium','Low','Open','Snoozed','True Positive','False Positive','Closed','Resolved']});break;
case 'incidents':listing('incidents','Incidents','Auto-correlated clusters of related alerts. Each incident represents one triage case across multiple findings on the same asset.',{group:'TRIAGE',filters:['Open','Investigating','Resolved','Closed']});break;
case 'alerts/suppressions':listing('rules','Alert Suppression Rules','Mute matching demo alerts. Rules apply to newly added demo alerts.',{add:'New rule',filters:['Active','Disabled','Title contains','Target match','Severity']});break;
case 'monitoring':listing('assets','Asset Monitoring','Continuous breach surveillance for your critical assets — simulated in this demo.',{add:'Add target',group:'CONTINUOUS MONITORING',filters:['Monitoring','Paused','Domain','Subdomain','Email','IP Address']});view.querySelector('.page-actions').insertAdjacentHTML('beforeend',action('Bulk import','import')+action('Check all now','scan'));break;
case 'assets':listing('assets','Asset Inventory',E(db.organization.domain)+' · '+db.assets.length+' assets discovered',{group:'ATTACK SURFACE',add:'Add asset',filters:['Domain','Subdomain','IP Address','Email','High','Medium','Low']});break;
case 'history':listing('history','Search History','View past demo searches and cached results.',{group:'ACTIVITY',filters:['Cached','Domain','Email','IP Address']});break;
case 'supply-chain':listing('vendors','Supply Chain Risk','Continuous security scoring for every vendor and partner.',{group:'THIRD-PARTY RISK',add:'Add vendor',filters:['High','Medium','Low','Monitoring']});view.insertAdjacentHTML('beforeend','<div class="feature-grid">'+['Network & Encryption','DNS & Email Hygiene','Patching Cadence','IP Reputation','Application Security','Active Threat Intelligence'].map(t=>card(t,'<p>Inspect vendor findings to review this risk category in the demo.</p>')).join('')+'</div>');break;
case 'executives':listing('executives','Executive Shield','Monitor sample executive exposure across breaches and stealer logs. Use fictional identities for this demo.',{group:'EXECUTIVE PROTECTION',add:'Add executive',filters:['Monitoring','High','Medium','Low']});break;
case 'exposure/credentials':listing('credentials','Credential Exposure','Leaked credentials across sample breach corpora and stealer-log drops.',{group:'EXPOSURE',filters:['Stealer log','Breach','Critical','High','Medium','Low']});break;
case 'rfi':listing('requests','Intel RFI','Submit and track demo requests for intelligence.',{add:'New request',group:'THREAT INTELLIGENCE',filters:['Open','Investigating','Resolved']});break;
case 'brand':renderBrand();break;case 'attack-paths':renderPaths();break;case 'attack-surface':renderSurface();break;case 'ask':renderAsk();break;case 'intelligence':renderIntel();break;case 'exposure':renderExposure();break;case 'dark-web':renderFeeds();break;case 'assessment':renderAssessment();break;case 'reports':renderReports();break;case 'org/settings':renderSettings();break;case 'demo-data':renderData();break;}bindView()}
function renderBrand(){intro('Brand Threats','One unified view of every brand-related finding. Registry, impersonators, takedowns, and resolutions all in one place.',action('File new takedown','add:brand','primary'),'BRAND PROTECTION');view.innerHTML+=stats([['NEEDS REVIEW',db.brand.filter(r=>r.status==='Needs review').length],['IN TAKEDOWN',db.brand.filter(r=>r.status==='In takedown').length],['RESOLVED',db.brand.filter(r=>r.status==='Resolved').length]])+tabs(['Threats','Setup']);if(selectedTab==='Setup'){view.innerHTML+=card('Brand registry',`<p>Primary brand: ${E(db.organization.name)}</p><p>Domain: ${E(db.organization.domain)}</p>${action('Edit brand settings','settings')}`);return}view.innerHTML+=table('brand',{filters:['Needs review','In takedown','Resolved','My domain','Not relevant']});}
function renderPaths(){intro('Attack Vectors','Drawn attack chains assembled from demo findings, ranked by severity.',action('Add finding','add:alerts'),'ADVERSARY GRAPH');view.innerHTML+=`<div class="path-grid">${db.alerts.slice(0,6).map((r,i)=>card('VECTOR '+String(i+1).padStart(2,'0'),`${badge(r.severity)}<h3>${E(r.title)}</h3><div class="attack-chain"><div>External actor</div><span>→</span><div>${E(r.type)}</div><span>→</span><div>${E(r.asset)}</div></div><p>Potential impact: unauthorized access to the affected demo asset.</p><button data-detail="alerts:${r.id}">Inspect evidence</button>`)).join('')}</div>`}
function renderSurface(){intro('Attack Surface','Subdomains, exposed services, vulnerabilities, and security posture for your organization.',action('Run scan','scan','primary'));view.innerHTML+=stats([['ASSETS',db.assets.length],['SUBDOMAINS',db.assets.filter(r=>r.type==='Subdomain').length],['HIGH RISK',db.assets.filter(r=>r.severity==='High').length],['FINDINGS',db.alerts.length]])+tabs(['Overview','Subdomains','Services','Vulnerabilities','Security Headers','TLS / SSL']);const t=selectedTab||'Overview';if(t==='Overview'){view.innerHTML+='<div class="feature-grid">'+card('Security posture','<div class="big">F</div><p>Missing security headers in the sample environment.</p>')+card('Infrastructure',db.assets.slice(0,5).map(r=>row(E(r.title),E(r.type))).join(''))+card('Exposure trend',chart())+'</div>'}else if(t==='Security Headers'||t==='TLS / SSL'){view.innerHTML+=card(t,['Strict-Transport-Security','Content-Security-Policy','X-Frame-Options','X-Content-Type-Options'].map(n=>row(t==='TLS / SSL'?'Certificate for '+E(db.organization.domain):n,t==='TLS / SSL'?'Valid':'Missing')).join(''))}else view.innerHTML+=table(t==='Vulnerabilities'?'alerts':'assets',{filters:['Domain','Subdomain','High','Medium','Low']});}
function renderAsk(){intro('eagle-i Chat','Explore your demo security data with simulated answers.');view.innerHTML+='<div class="chat"><p>Ask about exposures, alerts, vulnerabilities, credentials, or brand impersonation.</p><div class="suggestions">'+['What is my biggest risk right now?','What changed in the last 7 days?','Draft a board summary.','How many leaked credentials do I have?','Are any of my domains being impersonated?'].map(q=>`<button data-question="${q}">${q}</button>`).join('')+'</div><div id="messages" aria-live="polite"></div><form id="ask-form"><input name="question" required maxlength="500" placeholder="Ask about your security data…" aria-label="Ask about your security data"><button>Send →</button></form><small class="muted">Demo answers are generated from local sample records. No external AI or actions.</small></div>';}
function answer(question){const q=question.toLowerCase();let result=q.includes('credential')?`There are ${db.credentials.length} demo credential records. ${db.credentials.filter(r=>r.severity==='Critical').length} are critical.`:q.includes('imperson')||q.includes('domain')?`${db.brand.length} brand findings are tracked; ${db.brand.filter(r=>r.status==='Needs review').length} need review.`:q.includes('changed')?`The dataset contains ${db.history.length} search history records and ${db.alerts.length} alerts. Changes entered in this browser appear across the demo.`:`${db.organization.name} has an exposure score of ${db.score}/100, ${db.alerts.filter(r=>r.status==='Open').length} open alerts, and ${db.credentials.length} credential records. Prioritize critical alerts and review brand impersonation findings.`;document.querySelector('#messages').insertAdjacentHTML('beforeend',`<div class="chat-message user">${E(question)}</div><div class="chat-message"><span class="gold">eagle-i · Demo answer</span><p>${E(result)}</p></div>`)}
function renderIntel(){intro('Intelligence Hub','OSINT, security, and infrastructure analysis using fictional demo results.','','THREAT INTELLIGENCE');view.innerHTML+=tabs(['Domain','Email','IP Address','Username','Phone','IOC'])+card('Investigate',`<form id="intel-form"><input name="target" required maxlength="200" placeholder="Enter a ${(selectedTab||'domain').toLowerCase()}…" aria-label="Investigation target"><button class="primary">Scan</button></form><div id="intel-result"><div class="empty"><h3>Ready to investigate</h3><p>Enter a target to display simulated intelligence.</p></div></div>`)}
function renderExposure(){intro('Exposure Score',"Your organization's overall demo exposure rating",action('Scan now','scan','primary'),'EXPOSURE');view.innerHTML+='<div class="feature-grid">'+card('Exposure rating',`<div class="big">${db.score}<small> /100</small></div>${badge(db.score>=60?'High':db.score>=30?'Medium':'Low')}<p>Higher value = more exposure.</p>`)+card('Score history',chart())+card('Recommendations',db.alerts.filter(r=>r.severity==='Critical'||r.severity==='High').slice(0,4).map(r=>row(E(r.title),E(r.severity))).join(''))+'</div>'+card('Category Drill-Down',[['Credential Exposure',25,db.credentials.length+' exposed credentials'],['Vulnerabilities',20,db.alerts.filter(r=>r.title.toLowerCase().includes('vulnerab')).length+' findings'],['Exposed Services',10,'Demo risky ports'],['Phishing Domains',8,db.brand.length+' brand findings'],['Security Headers',8,'Grade F'],['Leaked Secrets',8,'Sample repository findings'],['SSL/TLS',7,'Valid'],['Login Panels',6,'Sample admin surfaces'],['Exposed Configs',5,'No findings'],['HTTP Plain-text',3,'HTTPS enforced']].map(([a,w,d])=>row(a,'Weight '+w+'%',d)).join(''));}
function renderFeeds(){intro('Dark Web Feeds','Sample threat intelligence feeds · Demo data','','THREAT INTELLIGENCE');view.innerHTML+=tabs(['Dashboard','Live Feed','Cyber News','Ransomware','Breaches','Vulnerabilities','Threat Intel','Initial Access Brokers','Brand Mentions']);if(!selectedTab||selectedTab==='Dashboard'){view.innerHTML+=stats([['TRACKED ITEMS',db.feeds.length],['RANSOMWARE',db.feeds.filter(r=>r.type==='Ransomware').length],['BREACHES',db.feeds.filter(r=>r.type==='Breaches').length]])+'<div class="feature-grid">'+card('Live activity',db.feeds.map(r=>row(E(r.title),E(r.type))).join(''))+card('Threat distribution',chart(true))+'</div>'}else{filter=['Live Feed','Cyber News','Brand Mentions'].includes(selectedTab)?'All':selectedTab;view.innerHTML+=table('feeds',{filters:['Ransomware','Breaches','Vulnerabilities','Threat Intel','Initial Access Brokers']})}view.innerHTML+=action('Add feed item','add:feeds');}
function renderAssessment(){intro('Posture Assessment','Twelve-section cyber posture review covering organization profile, exposure, security controls, and recommendations.');const names=['Organization','Threat Landscape','Mobile Surface','Malware Intel','Employee Creds','Customer Creds','Web Security','Email Security','TLS / SSL','Compliance','MITRE ATT&CK','Recommendations'];view.innerHTML+=tabs(names);const t=selectedTab||'Organization';const content=t==='Organization'?row('Organization',E(db.organization.name))+row('Industry',E(db.organization.industry))+row('Primary domain',E(db.organization.domain)):t.includes('Creds')?db.credentials.map(r=>row(E(r.title),E(r.severity))).join(''):t==='Recommendations'?db.alerts.slice(0,5).map(r=>row(E(r.title),E(r.severity))).join(''):t==='Compliance'?['NIST CSF','ISO 27001','SOC 2'].map(a=>row(a,'Review needed','Demo mapping only; not a compliance certification.')).join(''):t==='MITRE ATT&CK'?row('Initial Access','T1566','Phishing — sample brand findings')+row('Credential Access','T1552','Unsecured credentials — sample exposure records'):row('Assessment status','Demo review')+row('Related findings',db.alerts.length)+row('Exposure score',db.score+'/100')+'<p>Review the sample alerts and assets to investigate this control area.</p>';view.innerHTML+=card(t,content);}
function renderReports(){intro('Executive Reports','Generate demo threat intelligence reports for stakeholders.','','REPORTING');view.innerHTML+=tabs(['Templated Reports','AI Briefing']);if(selectedTab==='AI Briefing'){view.innerHTML+=card('Executive briefing',`<p>${E(db.organization.name)} has ${db.alerts.length} tracked alerts and ${db.assets.length} assets. Exposure is ${db.score}/100.</p>${action('Download briefing','report-download')}`);return}view.innerHTML+='<div class="feature-grid">'+['Executive Summary','Compliance Report'].map(t=>card(t,`<p>${t==='Executive Summary'?'High-level overview for board and C-suite':'NIST / ISO / SOC2 demo mapping'}</p><p><label class="field">Classification<select><option>Confidential</option><option>Public Use</option></select></label></p>${action('Generate report','report-generate')}`)).join('')+'</div>'+card('Scheduled Reports','<p>Create a demo schedule. No emails are sent.</p><form id="schedule-form"><label class="field">Frequency<select name="frequency"><option>Weekly (Mondays)</option><option>Monthly (1st)</option></select></label><label class="field">Recipients<input name="recipients" type="email" placeholder="ciso@example.com" required></label><button>Create schedule</button></form>')+table('reports',{filters:['Ready','Scheduled']});}
function renderSettings(){intro('Organization Settings','Manage your demo organization, team, and preferences.');view.innerHTML+=tabs(['Organization','Team','Preferences']);if(selectedTab==='Team'){view.innerHTML+=card('Demo team',row('Demo User','Owner','demo@example.com')+'<p>Team invites are simulated in this local demo.</p><form id="invite-form"><input name="email" type="email" required placeholder="teammate@example.com" aria-label="Teammate email"><button>Add demo member</button></form><div id="members"></div>');return}if(selectedTab==='Preferences'){view.innerHTML+=card('Appearance',action('Toggle light / dark','theme'))+card('Demo data','<p>Records are saved only in this browser. Export a backup to transfer your demo.</p>'+action('Manage demo data','data'));return}view.innerHTML+=card('Organization profile',`<form id="settings-form"><label class="field">Organization name<input name="name" value="${E(db.organization.name)}" required maxlength="160"></label><label class="field">Primary domain<input name="domain" value="${E(db.organization.domain)}" required maxlength="160"></label><label class="field">Industry<input name="industry" value="${E(db.organization.industry)}" required maxlength="160"></label><button class="primary">Save settings</button></form>`)+card('Scanner Whitelist','<p>This demo performs no network scans and needs no firewall allowlist.</p>');}
function renderData(){intro('Demo Data','Create, import, and manage dummy records. Changes stay in this browser.',action('Export JSON','export-json')+action('Reset sample data','reset'),'DEMO WORKSPACE');view.innerHTML+=stats([['RECORDS',DemoData.types.reduce((n,t)=>n+db[t].length,0)],['DATASETS',DemoData.types.length],['STORAGE','This browser']])+card('Insert dummy data',`<form id="generate-form"><label class="field">Dataset<select name="type">${DemoData.types.map(t=>`<option>${t}</option>`).join('')}</select></label><label class="field">Number of records<input name="count" type="number" min="1" max="100" value="10" required></label><button class="primary">Generate dummy records</button></form>`)+card('Import JSON','<p>Import a JSON object with dataset arrays. Each record needs a title; optional fields: asset, severity, status, type, notes, date. Imported datasets replace the matching datasets.</p><textarea id="json-import" aria-label="JSON data" rows="7" placeholder=\'{"assets":[{"title":"app.example.com","asset":"app.example.com","type":"Subdomain","status":"Monitoring"}]}\'></textarea><div class="page-actions"><input type="file" id="json-file" accept=".json,application/json" aria-label="Choose JSON file">'+action('Import data','import-json')+'</div><p id="import-error" role="alert"></p>')+card('Exposure score',`<form id="score-form"><label class="field">Score (0–100)<input type="number" min="0" max="100" name="score" value="${db.score}" required></label><button>Update score</button></form>`)+card('Datasets',DemoData.types.map(t=>row(E(t),`${db[t].length}　<button data-do="add:${t}">Add record</button>`)).join(''));}
function recordForm(type,id){const r=id?db[type].find(r=>r.id===id):null;modal(r?'Edit record':'Add '+type,`<form id="record-form"><label class="field">Title / name<input name="title" required maxlength="300" value="${E(r?.title||'')}"></label><label class="field">Asset / target<input name="asset" required maxlength="300" value="${E(r?.asset||db.organization.domain)}"></label><div class="form-columns"><label class="field">Severity<select name="severity">${['Critical','High','Medium','Low'].map(v=>`<option ${r?.severity===v?'selected':''}>${v}</option>`).join('')}</select></label><label class="field">Status<select name="status">${['Open','Monitoring','Paused','Investigating','Resolved','Closed','Snoozed','True Positive','False Positive','Needs review','In takedown','My domain','Not relevant','Active','Disabled','Ready','Scheduled','Published','Cached'].map(v=>`<option ${(r?.status||(['assets','vendors','executives'].includes(type)?'Monitoring':type==='brand'?'Needs review':type==='rules'?'Active':'Open'))===v?'selected':''}>${v}</option>`).join('')}</select></label></div><label class="field">Type<input name="type" maxlength="100" value="${E(r?.type||(type==='rules'?'Title contains':'Domain'))}" list="record-types"><datalist id="record-types">${['Domain','Subdomain','Email','IP Address','Breach','Stealer log','Title contains','Target match','Severity'].map(v=>`<option>${v}</option>`).join('')}</datalist></label><label class="field">Notes<textarea name="notes" maxlength="2000">${E(r?.notes||'')}</textarea></label><button class="primary">Save record</button>${r?' <button type="button" id="delete-record">Delete record</button>':''}</form>`);document.querySelector('#record-form').onsubmit=e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.target));const item={...DemoData.record(r?.id||type+'-'+Date.now()+'-'+Math.random().toString(36).slice(2),f.title.trim(),f.asset),...f,date:new Date().toISOString().slice(0,10)};if(!item.title.trim())return;if(r)db[type][db[type].indexOf(r)]=item;else{if(type==='alerts')applyRules(item);db[type].unshift(item)}save();dialog.close();render();toast('Demo record saved')};if(r)document.querySelector('#delete-record').onclick=()=>{db[type]=db[type].filter(x=>x.id!==r.id);save();dialog.close();render();toast('Record deleted')};}
function applyRules(r){const match=db.rules.some(rule=>rule.status==='Active'&&(rule.type==='Severity'?r.severity.toLowerCase()===rule.title.toLowerCase():rule.type==='Target match'?r.asset.toLowerCase()===rule.title.toLowerCase():r.title.toLowerCase().includes(rule.title.toLowerCase())));if(match)r.status='Snoozed'}
function detail(type,id){const r=db[type].find(r=>r.id===id);modal(r.title,`${badge(r.severity)}${row('Target',E(r.asset))}${row('Status',E(r.status))}${row('Type',E(r.type))}<p>${E(r.notes)}</p><div class="page-actions"><button id="detail-edit">Edit record</button>${type==='brand'?'<button id="takedown">Request demo takedown</button>':''}${['alerts','incidents','brand','requests'].includes(type)?'<button id="resolve">Mark resolved</button>':''}</div>`);document.querySelector('#detail-edit').onclick=()=>{dialog.close();recordForm(type,id)};let resolve=document.querySelector('#resolve');if(resolve)resolve.onclick=()=>{r.status='Resolved';save();dialog.close();render();toast('Marked resolved')};let take=document.querySelector('#takedown');if(take)take.onclick=()=>{r.status='In takedown';save();dialog.close();render();toast('Demo takedown started. No report was sent.')};}
function download(name,text,mime='application/json'){const u=URL.createObjectURL(new Blob([text],{type:mime}));let a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),500)}
function generate(type,count){if(!DemoData.types.includes(type)||!Number.isInteger(count)||count<1||count>100)throw Error('Choose a dataset and a count from 1 to 100.');if(db[type].length+count>1000)throw Error('Each dataset supports up to 1,000 records.');const offset=db[type].length;for(let i=0;i<count;i++){const n=offset+i+1;let r=DemoData.record(type+'-'+Date.now()+'-'+i,`${type==='assets'?'host-'+n+'.example.com':'Demo '+type+' record '+n}`,'host-'+n+'.example.com',['Critical','High','Medium','Low'][i%4],['assets','vendors','executives'].includes(type)?'Monitoring':type==='brand'?'Needs review':type==='rules'?'Active':type==='feeds'?'Published':'Open',type==='credentials'?'Breach':type==='rules'?'Title contains':'Domain');if(type==='alerts')applyRules(r);db[type].unshift(r)}save();render();return {dataset:type,added:count,total:db[type].length}}
function reportText(){return `${db.organization.name} — Demo Executive Report\n\nExposure score: ${db.score}/100\nAssets: ${db.assets.length}\nOpen alerts: ${db.alerts.filter(r=>r.status==='Open').length}\nCredential records: ${db.credentials.length}\nBrand threats: ${db.brand.length}\n\nPriority findings\n${db.alerts.slice(0,10).map(r=>r.severity+': '+r.title+' — '+r.asset).join('\n')}\n\nSimulated report based on local dummy data.`}
function doAction(cmd){const [a,t]=cmd.split(':');if(a==='add'){recordForm(t);return}if(a==='export'){const fields=['title','asset','severity','status','type','date','notes'];const cell=v=>'"'+String(v??'').replace(/^[=+@-]/,"'$&").replaceAll('"','""')+'"';download(t+'.csv',[fields.join(','),...db[t].map(r=>fields.map(f=>cell(r[f])).join(','))].join('\r\n'),'text/csv');return}switch(a){case 'scan':toast('Simulating scan…');setTimeout(()=>{db.history.unshift(DemoData.record('scan-'+Date.now(),'Demo scan completed',db.organization.domain,'Low','Cached','Scan'));save();toast('Demo scan complete. No external requests were made.')},1200);break;case 'settings':location.hash='/dashboard/org/settings';break;case 'data':case 'import':location.hash='/dashboard/demo-data';break;case 'theme':document.body.classList.toggle('light');break;case 'export-json':download('demo-data.json',JSON.stringify(db,null,2));break;case 'reset':modal('Reset demo data','<p>This replaces your local demo records. Export a JSON backup first if you want to keep them.</p><button id="confirm-reset">Reset to sample data</button>');document.querySelector('#confirm-reset').onclick=()=>{db=DemoData.seed();save();dialog.close();render();toast('Sample data restored')};break;case 'import-json':try{const raw=JSON.parse(document.querySelector('#json-import').value);db=DemoData.validate({...db,...raw});save();render();toast('Demo data imported')}catch(err){document.querySelector('#import-error').textContent=err.message}break;case 'report-generate':db.reports.unshift(DemoData.record('report-'+Date.now(),'Executive Summary',db.organization.domain,'Low','Ready','Report'));save();render();toast('Demo report generated');break;case 'report-download':download('demo-report.txt',reportText(),'text/plain');break;}}
function bindView(){view.querySelectorAll('[data-do]').forEach(b=>b.onclick=()=>doAction(b.dataset.do));view.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{selectedTab=b.dataset.tab;filter='All';query='';render()});view.querySelectorAll('[data-detail]').forEach(b=>b.onclick=()=>detail(...b.dataset.detail.split(':')));view.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>recordForm(...b.dataset.edit.split(':')));let searchInput=view.querySelector('#record-search');if(searchInput)searchInput.oninput=e=>{const pos=e.target.selectionStart;query=e.target.value;render();const n=view.querySelector('#record-search');n.focus();n.setSelectionRange(pos,pos)};for(const id of ['filter','sort']){const c=view.querySelector('#record-'+id);if(c)c.onchange=()=>{if(id==='filter')filter=c.value;else sort=c.value;render()}}const on=(id,fn)=>{const f=view.querySelector('#'+id);if(f)f.onsubmit=e=>{e.preventDefault();fn(Object.fromEntries(new FormData(f)),f)}};on('generate-form',f=>{try{generate(f.type,Number(f.count));toast('Dummy records added')}catch(e){toast(e.message)}});on('score-form',f=>{db.score=Number(f.score);save();toast('Score updated')});on('settings-form',f=>{db.organization=f;save();render();toast('Organization saved')});on('ask-form',(f,form)=>{answer(f.question);form.reset()});view.querySelectorAll('[data-question]').forEach(b=>b.onclick=()=>answer(b.dataset.question));on('intel-form',f=>{db.history.unshift(DemoData.record('search-'+Date.now(),f.target,f.target,'Low','Cached',selectedTab||'Domain'));save();document.querySelector('#intel-result').innerHTML='<p class="gold">Simulated intelligence results</p>'+row('Target',E(f.target))+row('Exposure score','40 /100')+row('Security headers','Grade F')+row('Credential findings','3 sample records')+'<p>No lookup was sent to external sources.</p>'});on('schedule-form',f=>{db.reports.unshift(DemoData.record('schedule-'+Date.now(),f.frequency,f.recipients,'Low','Scheduled','Demo schedule'));save();render();toast('Demo schedule saved. No emails will be sent.')});on('invite-form',(f,form)=>{document.querySelector('#members').insertAdjacentHTML('beforeend',row(E(f.email),'Demo member'));form.reset();toast('Demo member added for this session')});let upload=view.querySelector('#json-file');if(upload)upload.onchange=async()=>{const file=upload.files[0];if(!file)return;if(file.size>2000000){toast('Choose a JSON file under 2 MB');return}document.querySelector('#json-import').value=await file.text()};}
document.querySelector('#search').onclick=()=>{modal('Jump to page','<input id="route-query" placeholder="Search pages…" style="width:100%" aria-label="Search pages"><div id="route-results"></div>');const q=document.querySelector('#route-query');const update=()=>{document.querySelector('#route-results').innerHTML=routes.filter(r=>r[1].toLowerCase().includes(q.value.toLowerCase())).map(([r,n,g])=>`<a class="search-result" href="#/dashboard${r?'/'+r:''}">${n}<small>${g}</small></a>`).join('');document.querySelectorAll('.search-result').forEach(a=>a.onclick=()=>dialog.close())};q.oninput=update;update();q.focus()};search=()=>document.querySelector('#search').click();
document.addEventListener('click',e=>{const b=e.target.closest('[data-module],[data-action]');if(!b)return;e.stopImmediatePropagation();if(b.dataset.module){const map={'CREDENTIALS':'exposure/credentials','STEALER LOGS':'exposure/credentials','BREACHES':'exposure/credentials','DARK WEB':'dark-web','BRAND RISK':'brand','VULNERABILITIES':'attack-surface','SUPPLY CHAIN':'supply-chain','INFRASTRUCTURE':'assets'};location.hash='/dashboard/'+map[b.dataset.module];return}switch(b.dataset.action){case 'report':location.hash='/dashboard/reports';break;case 'refresh':syncDashboard();document.querySelector('#updated').textContent='Refreshed just now · local demo data';toast('Dashboard refreshed');break;case 'download':download('demo-report.txt',reportText(),'text/plain');break;case 'scan':doAction('scan');document.querySelector('#scan-status').textContent='Demo scan complete';document.querySelector('#scan-date').textContent=new Date().toLocaleString();break;case 'generate':document.querySelector('#narrative').innerHTML=`<ul><li>Exposure is ${db.score}/100.</li><li>${db.alerts.filter(r=>r.status==='Open').length} alerts are open.</li><li>${db.credentials.length} credential records are tracked.</li><li>${db.brand.filter(r=>r.status==='Needs review').length} brand findings need review.</li><li>${db.assets.length} assets are in the inventory.</li></ul>`;break}},true);
window.addEventListener('hashchange',navigate);syncDashboard();navigate();
if(document.modelContext?.registerTool){for(const tool of [{name:'read_demo_data',description:'Read counts of locally stored demo datasets.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({organization:db.organization,counts:Object.fromEntries(DemoData.types.map(t=>[t,db[t].length]))})},{name:'generate_dummy_records',description:'Insert fictional records into the local demo dataset and update the visible page.',inputSchema:{type:'object',properties:{dataset:{type:'string',enum:DemoData.types},count:{type:'integer',minimum:1,maximum:100}},required:['dataset','count'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>generate(input.dataset,input.count)}]){try{Promise.resolve(document.modelContext.registerTool(tool)).catch(()=>{})}catch{}}}
